    md=raw=0
    wp=os.path.join(p,'wiki')
    rp=os.path.join(p,'raw')
    for base, kind in [(wp,'md'),(rp,'raw')]:
        if os.path.isdir(base):
            for _,_,fs in os.walk(base):
                if kind=='md': md += sum(1 for f in fs if f.lower().endswith('.md'))
